from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    k = len(alphabet)
    if not banned:
        return pow(k, n, MOD)

    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}

    go: list[list[int]] = [[-1] * k]
    bad: list[bool] = [False]

    for word in banned:
        u = 0
        for ch in word:
            c = char_to_idx[ch]
            nxt = go[u][c]
            if nxt == -1:
                nxt = len(go)
                go[u][c] = nxt
                go.append([-1] * k)
                bad.append(False)
            u = nxt
        bad[u] = True

    fail = [0] * len(go)
    q: deque[int] = deque()

    for c in range(k):
        v = go[0][c]
        if v != -1:
            fail[v] = 0
            q.append(v)
        else:
            go[0][c] = 0

    while q:
        u = q.popleft()
        fu = fail[u]
        for c in range(k):
            v = go[u][c]
            if v != -1:
                fv = go[fu][c]
                fail[v] = fv
                if bad[u] or bad[fv]:
                    bad[v] = True
                q.append(v)
            else:
                go[u][c] = go[fu][c]

    safe_id = [-1] * len(go)
    safe_states: list[int] = []
    for u in range(len(go)):
        if not bad[u]:
            safe_id[u] = len(safe_states)
            safe_states.append(u)

    m = len(safe_states)
    base = [[0] * m for _ in range(m)]
    for i, u in enumerate(safe_states):
        row = base[i]
        for c in range(k):
            j = safe_id[go[u][c]]
            if j != -1:
                row[j] += 1

    vec = [0] * m
    vec[0] = 1

    exp = n
    while exp > 0:
        if exp & 1:
            new_vec = [0] * m
            for i in range(m):
                vi = vec[i]
                if vi:
                    row = base[i]
                    for j in range(m):
                        new_vec[j] += vi * row[j]
            vec = [x % MOD for x in new_vec]
        exp >>= 1
        if exp > 0:
            new_base = [[0] * m for _ in range(m)]
            for i in range(m):
                row_i = base[i]
                res_i = new_base[i]
                for p in range(m):
                    val = row_i[p]
                    if val:
                        row_p = base[p]
                        for j in range(m):
                            res_i[j] += val * row_p[j]
                for j in range(m):
                    res_i[j] %= MOD
            base = new_base

    return sum(vec) % MOD
